import{_ as e,o as n,c as i,a2 as l}from"./chunks/framework.Brv5O9VI.js";const u=JSON.parse('{"title":"14.18 Architecture Decision Records (ADR Log)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),s={name:"system-design/decisions.md"};function a(r,t,d,o,c,g){return n(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_14-18-architecture-decision-records-adr-log" tabindex="-1">14.18 Architecture Decision Records (ADR Log) <a class="header-anchor" href="#_14-18-architecture-decision-records-adr-log" aria-label="Permalink to &quot;14.18 Architecture Decision Records (ADR Log)&quot;">​</a></h1><p>This log records every major architectural and technical decision made across the <strong>21-BIS-Compliance-Engine</strong>, documenting the chosen approach, alternatives evaluated, trade-offs accepted, and triggers to revisit.</p><hr><h2 id="master-architecture-decisions-table" tabindex="-1">Master Architecture Decisions Table <a class="header-anchor" href="#master-architecture-decisions-table" aria-label="Permalink to &quot;Master Architecture Decisions Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Decision</th><th style="text-align:left;">Chosen Option</th><th style="text-align:left;">Alternatives Considered</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Trade-off Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Backend Web Framework</strong></td><td style="text-align:left;"><strong>FastAPI (Python 3.11)</strong></td><td style="text-align:left;">Express.js, Flask, Django, Go Gin, Spring Boot</td><td style="text-align:left;">Direct in-memory zero-copy pointer sharing with Python ML/NumPy arrays; async ASGI; Pydantic v2 validation</td><td style="text-align:left;">Python GIL limits single-process thread concurrency</td><td style="text-align:left;">Backend logic separates into high-throughput I/O gateway requiring Go/Rust</td></tr><tr><td style="text-align:left;"><strong>Vector Embedding Model</strong></td><td style="text-align:left;"><strong>FastEmbed ONNX (<code>bge-small-en-v1.5</code>)</strong></td><td style="text-align:left;">OpenAI <code>text-embedding-3-small</code>, PyTorch SentenceTransformers, HuggingFace API</td><td style="text-align:left;">Strips away 1.2GB PyTorch dependency; cuts RAM to 60MB; runs in 14ms on CPU; zero cloud token costs</td><td style="text-align:left;">CPU-bound computation at high concurrency bursts</td><td style="text-align:left;">Queries exceed 1,000 RPS, requiring dedicated GPU/TensorRT inference sidecars</td></tr><tr><td style="text-align:left;"><strong>Vector Search Engine</strong></td><td style="text-align:left;"><strong>FAISS CPU (<code>IndexFlatIP</code>)</strong></td><td style="text-align:left;">Pinecone, pgvector, Weaviate, Qdrant, Milvus, ChromaDB</td><td style="text-align:left;">100% exact cosine recall (no approximation loss); &lt;0.2ms search latency; operates 100% in RAM with zero cloud fees</td><td style="text-align:left;">Flat scan scales as $O(N)$ linearly with corpus size</td><td style="text-align:left;">Corpus grows beyond 50,000 standards, requiring HNSW or IVF index quantization</td></tr><tr><td style="text-align:left;"><strong>Department Classifier</strong></td><td style="text-align:left;"><strong>Scikit-Learn Serialized Pipeline (<code>v3.pkl</code>)</strong></td><td style="text-align:left;">Fine-tuned BERT, LLM few-shot prompting, Zero-shot NLI</td><td style="text-align:left;">Sub-0.1ms inference; deterministic closed-set routing; zero neural network compute</td><td style="text-align:left;">Cannot easily predict novel, unseen ministry categories</td><td style="text-align:left;">Dynamic multi-level hierarchical ministerial taxonomies are introduced</td></tr><tr><td style="text-align:left;"><strong>Domain Safety Guardrail</strong></td><td style="text-align:left;"><strong>4-Tier Deterministic Rules (<code>guardrail.py</code>)</strong></td><td style="text-align:left;">LLM moderator prompt, Llama Guard, OpenAI Moderation API</td><td style="text-align:left;">Sub-0.05ms execution; zero API dependencies; 100% accuracy on adversarial test suites</td><td style="text-align:left;">Requires manual maintenance of commercial keyword blacklists</td><td style="text-align:left;">Unregulated product categories become too vast for keyword lists</td></tr><tr><td style="text-align:left;"><strong>Readiness Scoring Engine</strong></td><td style="text-align:left;"><strong>Rule-Based Weighted Checklists (<code>gap_engine.py</code>)</strong></td><td style="text-align:left;">LLM compliance estimation, Fuzzy neural scoring</td><td style="text-align:left;">100% mathematically reproducible and auditable in legal/court proceedings</td><td style="text-align:left;">Fixed criteria weights cannot capture subjective auditor nuances</td><td style="text-align:left;">Dynamic clause-level severity scoring is required per product</td></tr><tr><td style="text-align:left;"><strong>Audit Pack Export Format</strong></td><td style="text-align:left;"><strong>RFC 4180 CSV Stream</strong></td><td style="text-align:left;">PDF generation (Puppeteer/WeasyPrint), Excel <code>.xlsx</code></td><td style="text-align:left;">Lightweight native Python generation with zero headless browser dependencies; directly importable into ERP/Excel</td><td style="text-align:left;">Plain text layout without visual certificate branding</td><td style="text-align:left;">Enterprise customers mandate cryptographically signed, branded PDF certificates</td></tr><tr><td style="text-align:left;"><strong>Conversational Intent Handling</strong></td><td style="text-align:left;"><strong>Prefix &amp; Substring Short-Circuit</strong></td><td style="text-align:left;">LLM intent routing, Rasa NLU, Dialogflow</td><td style="text-align:left;">Sub-microsecond execution; prevents misinterpreting greetings as product queries</td><td style="text-align:left;">Limited flexibility for ambiguous user phrasing</td><td style="text-align:left;">Multi-turn conversational dialog and context memory are added</td></tr><tr><td style="text-align:left;"><strong>Frontend Architecture</strong></td><td style="text-align:left;"><strong>React 19 SPA + Vite 8</strong></td><td style="text-align:left;">Next.js (App Router), Vue 3, Svelte 5, Angular</td><td style="text-align:left;">Fast HMR (&lt;50ms); 140KB production bundle; internal tool does not require public SEO</td><td style="text-align:left;">Client-rendered (no initial server-side HTML rendering)</td><td style="text-align:left;">Public SEO-indexed consumer standard search portal is launched</td></tr><tr><td style="text-align:left;"><strong>UI Styling Strategy</strong></td><td style="text-align:left;"><strong>Inline Vanilla CSS Objects</strong></td><td style="text-align:left;">Tailwind CSS, Material UI, styled-components</td><td style="text-align:left;">Zero build-step dependencies; zero class-name collisions; self-contained in <code>App.jsx</code></td><td style="text-align:left;">Styles cannot be extracted into external cached CSS files</td><td style="text-align:left;">Application expands beyond a single dashboard into a multi-page portal</td></tr><tr><td style="text-align:left;"><strong>Master Knowledge Base Storage</strong></td><td style="text-align:left;"><strong>Static JSON File (<code>model2_corpus.json</code>)</strong></td><td style="text-align:left;">MongoDB, PostgreSQL, SQLite, Redis</td><td style="text-align:left;">Immutable, read-only dataset; loads into RAM in 0.5ms; zero database connection overhead</td><td style="text-align:left;">Modifying standards requires running rebuild scripts and restarting process</td><td style="text-align:left;">Multi-tenant dynamic standard uploads by external contributors</td></tr><tr><td style="text-align:left;"><strong>Containerization Strategy</strong></td><td style="text-align:left;"><strong>Python 3.11-slim Single Container</strong></td><td style="text-align:left;">Multi-container Docker Compose, Alpine base</td><td style="text-align:left;">Debian slim provides pre-compiled glibc wheels for FAISS and NumPy without compiler bloat</td><td style="text-align:left;">280MB image is slightly larger than Alpine (which frequently fails building FAISS)</td><td style="text-align:left;">Microservices decoupling splits frontend and backend containers</td></tr><tr><td style="text-align:left;"><strong>API Versioning</strong></td><td style="text-align:left;"><strong>Unversioned Root Routes (<code>/chat</code>)</strong></td><td style="text-align:left;">URI versioning (<code>/v1/chat</code>), Header versioning</td><td style="text-align:left;">Simple MVP demonstration interface</td><td style="text-align:left;">Breaking changes to JSON schemas could affect existing clients</td><td style="text-align:left;">Public developer APIs and third-party partner integrations are exposed</td></tr></tbody></table>',5)])])}const f=e(s,[["render",a]]);export{u as __pageData,f as default};
